const state={route:"welcome",studio:null,builder:null,fields:[],workflow:null,step:0,returnToReview:false,generating:false,form:{},project:null,result:null,mockupForm:null,mockupResult:null,mockupSkipped:false,kidsProduct:null,kidsProductForm:null,kidsProductResult:null,kidsProductSkipped:false,kidsCatalogQuery:"",kidsCatalogCategory:"all",kidsCatalogClassification:"all",kidsCatalogAge:"all",adultProduct:null,adultProductForm:null,adultProductResult:null,adultProductSkipped:false,adultCatalogQuery:"",adultCatalogCategory:"all",adultCatalogClassification:"all",dirty:false,filter:"all",sort:"newest",query:"",builderFilter:"all"};
