  const hash=route==="studio"&&state.studio?`#/${state.studio}-studio/dashboard`:route==="builder"?`#/${state.studio}-studio/builder/${state.builder?.id}`:route==="result"?`#/${state.studio}-studio/result`:route==="mockup-builder"?"#/sticker-studio/mockup-builder":route==="mockup-result"?"#/sticker-studio/mockup-result":route.startsWith("kids-product-")?`#/kids-studio/${route}`:route.startsWith("adult-product-")?`#/character-studio/${route}`:`#/${route}`;
