function finishKidsProductGeneration(){const generated=generateKidsProduct(state.project,state.form,state.result,state.kidsProduct,state.kidsProductForm);if(generated.errors.length)return showDialog("Let’s fix the product",`<ul>${generated.errors.map(error=>`<li>${esc(error)}</li>`).join("")}</ul>`,[{label:"Return to product builder",value:"close"}]);state.kidsProductResult=generated;state.dirty=true;navigate("kids-product-result")}
function currentKidsProductEntry(){const existing=(state.project?.products||[]).find(item=>item.productId===state.kidsProductForm?.productId),now=new Date().toISOString();return {productId:state.kidsProductForm.productId,productTitle:state.kidsProductForm.productTitle,productType:state.kidsProduct.name,productCategory:state.kidsProduct.category,classification:state.kidsProductForm.classification,formData:clone(state.kidsProductForm),prompt:state.kidsProductResult.prompt,negativePrompt:state.kidsProductResult.negative,summary:state.kidsProductResult.summary,favorite:existing?.favorite||false,createdAt:existing?.createdAt||now,updatedAt:now,status:"completed"}}
function saveKidsProduct(){if(!state.kidsProductResult)return;const entry=currentKidsProductEntry(),products=[...(state.project.products||[])],index=products.findIndex(item=>item.productId===entry.productId);if(index>=0)products[index]=entry;else products.push(entry);state.project=store.saveProject({...state.project,productEnabled:true,productStatus:"completed",productType:entry.productType,productCategory:entry.productCategory,productFormData:entry.formData,productPrompt:entry.prompt,productNegativePrompt:entry.negativePrompt,productCreatedAt:state.project.productCreatedAt||entry.createdAt,productUpdatedAt:entry.updatedAt,productFavorite:entry.favorite,linkedProductIds:products.map(item=>item.productId),products});state.dirty=false;toast("Linked Product saved inside the Original Kids Project");renderKidsProductResultV2()}
