function openKidsProductVariant(id){const entry=(state.project?.products||[]).find(item=>item.productId===id);if(!entry)return toast("That linked product could not be found.","error");state.kidsProduct=productByName(entry.productType);if(!state.kidsProduct)return toast("That product format is no longer available.","error");state.kidsProductForm=clone(entry.formData);state.kidsProductResult={prompt:entry.prompt,negative:entry.negativePrompt,summary:entry.summary};navigate("kids-product-result")}
function renderKidsProductResult(){if(!state.kidsProductResult||!state.kidsProductForm||state.studio!=="kids")return navigate("result");const entry=(state.project.products||[]).find(item=>item.productId===state.kidsProductForm.productId),summary=state.kidsProductResult.summary;main.innerHTML=`<section class="studio-shell studio-shell--kids screen kids-product-screen"><article class="result-card result-card--kids kids-product-result"><p class="eyebrow">Linked Kids Product</p><h1 class="display-title">Your Product Prompt Is Ready</h1><p class="sr-only" role="status" aria-live="polite">The Kids product prompt has been generated successfully.</p><div class="project-card__meta"><span class="badge">Source: ${esc(state.project.title)}</span><span class="badge">${esc(summary.productType)}</span><span class="badge">${esc(summary.classification)}</span><span class="badge">${esc(summary.sides)}</span><span class="badge">${esc(summary.itemCount)} item${summary.itemCount===1?"":"s"}</span></div><h2>${esc(summary.productTitle)}</h2><h3>Product prompt</h3><div class="prompt-box" id="kids-product-prompt">${esc(state.kidsProductResult.prompt)}</div><button class="button button--primary" data-copy="kids-product">Copy Product Prompt</button><h3>Product negative prompt</h3><div class="prompt-box" id="kids-product-negative">${esc(state.kidsProductResult.negative)}</div><button class="button" data-copy="kids-product-negative">Copy Product Negative Prompt</button><h3>Character and visual consistency</h3><div class="prompt-box">${esc(summary.consistency)}</div><h3>Exact visible text</h3><div class="prompt-box">${esc(summary.exactText)}</div><div class="button-row product-result-actions"><button class="button button--primary" data-action="save-kids-product">Save Product</button><button class="button" data-action="favorite-kids-product">${entry?.favorite?"♥ Favorited Product":"♡ Favorite Product"}</button><button class="button" data-action="download-kids-product">Download TXT</button><button class="button" data-action="export-kids-product">Export Product JSON</button><button class="button" data-action="edit-kids-product">Edit Product</button><button class="button" data-action="regenerate-kids-product">Regenerate Product</button><button class="button" data-action="duplicate-kids-product">Duplicate Only This Product</button><button class="button" data-action="another-kids-product">Create Another Product</button><button class="button" data-action="return-kids-result">Return to Kids Result</button><button class="button" data-action="back-dashboard">Return to Kids Dashboard</button></div></article></section>`}
