function renderMockupBuilder(){if(state.studio!=="sticker"||!state.project||!state.result)return navigate("result");if(!state.mockupForm)state.mockupForm=inheritedMockupForm(state.form);main.innerHTML=`<section class="studio-shell studio-shell--sticker screen mockup-screen"><div class="section-heading"><div><p class="eyebrow">Optional Sticker Studio workflow</p><h1 class="display-title">Create a Product Mockup</h1><p class="lead">Review inherited project details and choose a professional presentation.</p></div><button class="button" data-action="return-sticker-result">Return to Sticker Result</button></div>${mockupInheritedSummary()}<div class="mockup-assist button-row"><button class="button" data-action="style-mockup">Style My Mockup</button><button class="button" data-action="surprise-mockup">Surprise My Mockup</button></div><form class="mockup-builder" data-mockup-form>${mockupGroups.map(group=>`<fieldset class="panel mockup-group"><legend>${esc(group.title)}</legend>${group.fields.map(mockupField).join("")}</fieldset>`).join("")}<div class="mockup-sticky-actions"><button class="button" type="button" data-action="return-sticker-result">Cancel</button><button class="button button--primary" type="button" data-action="generate-mockup">Generate Mockup Prompt</button></div></form></section>`;}
function readMockupField(target){const id=target.dataset.mockupField;if(!id||!state.mockupForm)return;if(target.type==="checkbox")state.mockupForm[id]=[...document.querySelectorAll(`[data-mockup-field="${CSS.escape(id)}"]:checked`)].map(item=>item.value);else state.mockupForm[id]=target.value;state.dirty=true}
