dialogLayer.addEventListener("click",event=>{
  if(event.target.matches("[data-dialog-close]"))return closeDialog();const button=event.target.closest("[data-dialog-value]");if(!button)return;const value=button.dataset.dialogValue;if(value==="close")closeDialog();if(value==="propose-style"){const concept=document.querySelector("#style-concept")?.value.trim();if(!concept)return toast("Describe a concept first.","error");proposeStyle(concept);}if(value==="style-me")showStyleMe();if(value==="accept-style"||value==="accept-surprise"){const proposal=JSON.parse(dialogLayer.dataset.proposal||"{}");closeDialog();startBuilder(studio().builders[0].id,proposal);}if(value==="surprise-again")surprise();if(value==="restyle-mockup")mockupProposal("style");if(value==="resurprise-mockup")mockupProposal("surprise");if(value==="accept-mockup-proposal"){state.mockupForm=JSON.parse(dialogLayer.dataset.mockupProposal||"{}");closeDialog();renderMockupBuilder()}if(value==="restyle-kids-product")kidsProductProposalV2("style");if(value==="resurprise-kids-product")kidsProductProposalV2("surprise");if(value==="accept-kids-product-proposal"){const proposal=JSON.parse(dialogLayer.dataset.kidsProductProposal||"{}");state.kidsProduct=productByName(proposal.productName);state.kidsProductForm=proposal.form;closeDialog();renderKidsProductBuilderV2()}if(value.startsWith("delete:")){const [,s,id]=value.split(":");store.deleteProject(s,id);closeDialog();toast("Project deleted");renderProjects();}if(value.startsWith("reset:")){store.resetStudio(value.split(":")[1]);closeDialog();toast("Studio data reset");}if(value==="confirm-clear-history"){["character","kids","sticker"].forEach(s=>store.clearHistory(s));closeDialog();renderHistory();}if(value==="confirm-reset-all"){store.resetAll();closeDialog();applySettings();navigate("home");toast("Nyvera reset complete");}if(value==="confirm-project-import"){const data=JSON.parse(dialogLayer.dataset.import||"{}");data.id=null;data.title=`${data.title} Imported`;store.saveProject(data);closeDialog();toast("Project imported");navigate("projects");}if(value==="import-merge"||value==="import-replace"){const data=JSON.parse(dialogLayer.dataset.import||"{}");store.importAll(data,value==="import-merge"?"merge":"replace");closeDialog();applySettings();toast("Nyvera data imported");renderSettings();}
});
